#pragma once
// =============================================================================
//  TubeSaturator - 4x oversampled asymmetric "tube" waveshaper
//
//  * asymmetric tanh (bias) -> even + odd harmonics like a single-ended triode
//  * 4x oversampling with two cascaded Kaiser-windowed half-band FIR stages,
//    so harmonics generated by the shaper do not alias back into the audio band
//  * automatic level compensation: a full-volume note keeps roughly the same
//    peak level, quiet notes get "squeezed" - the soft compression of a tube amp
// =============================================================================
#include "DspUtils.h"
#include <vector>

namespace av
{
/** Simple 2x half-band FIR resampler (direct form, double-length circular history). */
class HalfBand2x
{
public:
    void design (int numTaps, double beta)
    {
        taps = numTaps | 1;
        const int M = taps / 2;
        h.assign ((size_t) taps, 0.0f);
        const double i0b = besselI0 (beta);
        double sum = 0.0;
        for (int n = 0; n < taps; ++n)
        {
            const int    k   = n - M;
            const double x   = 0.5 * k;                               // fc = 0.25
            const double sinc = (k == 0) ? 1.0 : std::sin (kPi * x) / (kPi * x);
            const double r   = (double) (n - M) / (double) M;
            const double win = besselI0 (beta * std::sqrt (std::max (0.0, 1.0 - r * r))) / i0b;
            h[(size_t) n] = (float) (0.5 * sinc * win);
            sum += h[(size_t) n];
        }
        for (auto& c : h) c = (float) (c / sum);                     // unity DC gain
        upHist.assign ((size_t) taps * 2, 0.0f);
        dnHist.assign ((size_t) taps * 2, 0.0f);
        upPos = dnPos = 0;
    }

    void reset()
    {
        std::fill (upHist.begin(), upHist.end(), 0.0f);
        std::fill (dnHist.begin(), dnHist.end(), 0.0f);
        upPos = dnPos = 0;
    }

    /** One input sample -> two output samples. */
    inline void up (float x, float& o0, float& o1)
    {
        o0 = pushAndFilter (upHist, upPos, 2.0f * x);
        o1 = pushAndFilter (upHist, upPos, 0.0f);
    }

    /** Two input samples -> one output sample. */
    inline float down (float a, float b)
    {
        pushAndFilter (dnHist, dnPos, a);
        return pushAndFilter (dnHist, dnPos, b);
    }

    /** Group delay in samples of the HIGH rate. */
    int groupDelay() const { return taps / 2; }

private:
    inline float pushAndFilter (std::vector<float>& hist, int& pos, float x)
    {
        pos = (pos == 0) ? taps - 1 : pos - 1;
        hist[(size_t) pos] = x;
        hist[(size_t) (pos + taps)] = x;
        const float* p = hist.data() + pos;
        float acc = 0.0f;
        for (int k = 0; k < taps; ++k) acc += h[(size_t) k] * p[k];
        return acc;
    }

    static double besselI0 (double x)
    {
        double sum = 1.0, term = 1.0;
        for (int k = 1; k < 40; ++k) { term *= (x / (2.0 * k)) * (x / (2.0 * k)); sum += term; }
        return sum;
    }

    int taps = 1, upPos = 0, dnPos = 0;
    std::vector<float> h, upHist, dnHist;
};

class TubeSaturator
{
public:
    void prepare (double sampleRate)
    {
        fs = sampleRate;
        stage1.design (63, 7.0);   // fs   <-> 2fs  (steep)
        stage2.design (23, 7.0);   // 2fs  <-> 4fs  (relaxed, signal already band-limited)
        drive.reset (fs, 0.03, drive.target);
        dc.prepare (fs, 6.0f);
        reset();
    }

    void reset() { stage1.reset(); stage2.reset(); dc.reset(); }

    void setDrive (float amount) { drive.setTarget (clampv (amount, 0.0f, 1.0f)); }

    /** Latency in base-rate samples (rounded). */
    int getLatencySamples() const
    {
        const double d = 2.0 * (stage1.groupDelay() / 2.0 + stage2.groupDelay() / 4.0);
        return (int) std::lround (d);
    }

    void process (float* x, int n)
    {
        for (int i = 0; i < n; ++i)
        {
            const float d    = drive.next();
            const float g    = 1.0f + 60.0f * std::pow (d, 1.5f); // up to ~36 dB of drive, bites early
            const float bias = 0.45f * d;                     // asymmetry -> even harmonics
            const float tb   = std::tanh (bias);
            // level compensation, but let a hard-driven tube get a little louder and grittier
            const float comp = (0.7f + 0.35f * d) / (std::tanh (0.7f * g + bias) - tb);

            float a0, a1, b0, b1, b2, b3;
            stage1.up (x[i], a0, a1);
            stage2.up (a0, b0, b1);
            stage2.up (a1, b2, b3);

            b0 = (std::tanh (g * b0 + bias) - tb) * comp;
            b1 = (std::tanh (g * b1 + bias) - tb) * comp;
            b2 = (std::tanh (g * b2 + bias) - tb) * comp;
            b3 = (std::tanh (g * b3 + bias) - tb) * comp;

            const float c0 = stage2.down (b0, b1);
            const float c1 = stage2.down (b2, b3);
            x[i] = dc.process (stage1.down (c0, c1));
        }
    }

private:
    double fs = 48000.0;
    HalfBand2x stage1, stage2;
    LinearSmoother drive;
    DCBlocker dc;
};
} // namespace av
